// Consolidated current frontend bundle.
const __market = (() => {
const CACHE_KEY = "h9-live-market-prices-v1";
const assetKeys = {
  Gold: "gold",
  Oil: "oil",
  Electricity: "electricity",
  "S&P 500": "sp500",
  NASDAQ: "nasdaq",
  Tesla: "tesla",
  "Artificial intelligence": "artificialIntelligence",
  Bitcoin: "bitcoin",
  Ethereum: "ethereum",
  "Dow Jones": "dowJones",
  "Russell 2000": "russell2000",
  Silver: "silver",
  "Natural gas": "naturalGas",
  Copper: "copper",
  "EUR/USD": "euroUsd",
};

function readCache() {
  try {
    const saved = JSON.parse(localStorage.getItem(CACHE_KEY) || "{}");
    return saved?.quotes && typeof saved.quotes === "object" ? saved : { quotes: {}, fetchedAt: 0 };
  } catch {
    return { quotes: {}, fetchedAt: 0 };
  }
}

let marketCache = readCache();

function getMarketQuote(assetName) {
  const key = assetKeys[assetName];
  return key ? marketCache.quotes[key] || null : null;
}

function applyMarketQuoteData(data) {
  const nextQuotes = { ...marketCache.quotes };
  for (const [key, quote] of Object.entries(data?.quotes || {})) {
    const price = Number(quote?.price);
    const marketAt = Number(quote?.marketAt);
    if (Number.isFinite(price) && (key === 'electricity' || price > 0) && Number.isFinite(marketAt) && marketAt > 0) {
      nextQuotes[key] = { ...quote, price, marketAt };
    }
  }
  if (Object.keys(nextQuotes).length) {
    marketCache = { quotes: nextQuotes, fetchedAt: Number(data?.fetchedAt) || Date.now() };
    try { localStorage.setItem(CACHE_KEY, JSON.stringify(marketCache)); } catch {}
  }
  return marketCache.quotes;
}

async function refreshMarketQuotes() {
  try {
    const response = await fetch("/api/asset-prices?electricity=" + encodeURIComponent(electricityMarket()), { cache: "no-store" });
    if (response.ok) applyMarketQuoteData(await response.json());
  } catch {}
  return marketCache.quotes;
}

const electricityMarket = () => localStorage.getItem("you-invest-electricity-market") || "DE-LU";
const HISTORY_CACHE_KEY = "h9-live-market-history-v7-" + electricityMarket();

function readHistoryCache() {
  try {
    const saved = JSON.parse(localStorage.getItem(HISTORY_CACHE_KEY) || "null");
    return saved?.histories && typeof saved.histories === "object"
      ? { histories: saved.histories, candles: saved.candles || {}, intraday: saved.intraday || {}, fetchedAt: Number(saved.fetchedAt) || 0 }
      : null;
  } catch {
    return null;
  }
}

let marketHistory = readHistoryCache();

function getMarketHistory() {
  return marketHistory;
}

async function refreshMarketHistory() {
  try {
    const response = await fetch("/api/asset-history?electricity=" + encodeURIComponent(electricityMarket()), { cache: "no-store" });
    if (!response.ok) return marketHistory;
    const data = await response.json();
    const histories = Object.fromEntries(Object.entries(data?.histories || {}).flatMap(([key, points]) => {
      const valid = Array.isArray(points)
        ? points.map((point) => ({ time: Number(point.time), value: Number(point.value) }))
          .filter((point) => Number.isFinite(point.time) && Number.isFinite(point.value))
          .sort((a, b) => a.time - b.time)
        : [];
      return valid.length ? [[key, valid]] : [];
    }));
    const candles = Object.fromEntries(Object.entries(data?.candles || {}).flatMap(([key, items]) => {
      const valid = Array.isArray(items) ? items.map((item) => ({
        time: Number(item.time), open: Number(item.open), high: Number(item.high),
        low: Number(item.low), close: Number(item.close),
      })).filter((item) => Number.isFinite(item.time) && [item.open, item.high, item.low, item.close].every(Number.isFinite))
        .sort((a, b) => a.time - b.time) : [];
      return valid.length ? [[key, valid]] : [];
    }));
    const intraday = Object.fromEntries(Object.entries(data?.intraday || {}).flatMap(([key, points]) => {
      const valid = Array.isArray(points) ? points.map((point) => ({ time: Number(point.time), value: Number(point.value) }))
        .filter((point) => Number.isFinite(point.time) && Number.isFinite(point.value))
        .sort((a, b) => a.time - b.time) : [];
      return valid.length ? [[key, valid]] : [];
    }));
    if (!Object.keys(histories).length && !Object.keys(candles).length && !Object.keys(intraday).length) return marketHistory;
    marketHistory = {
      histories: { ...(marketHistory?.histories || {}), ...histories },
      candles: { ...(marketHistory?.candles || {}), ...candles },
      intraday: { ...(marketHistory?.intraday || {}), ...intraday },
      fetchedAt: Number(data.fetchedAt) || Date.now(),
    };
    try { localStorage.setItem(HISTORY_CACHE_KEY, JSON.stringify(marketHistory)); } catch {}
  } catch {}
  return marketHistory;
}

return { getMarketQuote, refreshMarketQuotes, applyMarketQuoteData, getMarketHistory, refreshMarketHistory };
})();
const { getMarketQuote, refreshMarketQuotes, applyMarketQuoteData, getMarketHistory, refreshMarketHistory } = __market;
const __investment = (() => {
const allocationSets = {
  sixMonths: [
    ['Gold','Commodities',10],['Oil','Commodities',7],['Electricity','Energy',8],['S&P 500','US equities',12],['NASDAQ','Technology equities',10],['Tesla','Individual stocks',4],['Artificial intelligence','Technology',8],['Bitcoin','Crypto',4],['Ethereum','Crypto',3],['Dow Jones','US equities',8],['Russell 2000','US small-cap equities',6],['Silver','Commodities',5],['Natural gas','Energy',5],['Copper','Commodities',4],['EUR/USD','Foreign exchange',6],
  ],
  oneYear: [
    ['Gold','Commodities',8],['Oil','Commodities',7],['Electricity','Energy',8],['S&P 500','US equities',12],['NASDAQ','Technology equities',12],['Tesla','Individual stocks',6],['Artificial intelligence','Technology',10],['Bitcoin','Crypto',5],['Ethereum','Crypto',4],['Dow Jones','US equities',7],['Russell 2000','US small-cap equities',6],['Silver','Commodities',4],['Natural gas','Energy',4],['Copper','Commodities',3],['EUR/USD','Foreign exchange',4],
  ],
  longTerm: [
    ['Gold','Commodities',8],['Oil','Commodities',6],['Electricity','Energy',6],['S&P 500','US equities',14],['NASDAQ','Technology equities',14],['Tesla','Individual stocks',7],['Artificial intelligence','Technology',12],['Bitcoin','Crypto',8],['Ethereum','Crypto',7],['Dow Jones','US equities',6],['Russell 2000','US small-cap equities',4],['Silver','Commodities',3],['Natural gas','Energy',2],['Copper','Commodities',2],['EUR/USD','Foreign exchange',1],
  ],
};

const PLANS = [6, 12, 24, 36, 60].map((months) => ({
  id: 'plan-' + months + 'm',
  name: months === 6 ? '6-month plan' : (months / 12) + '-year plan',
  months,
  allocations: allocationSets[months === 6 ? 'sixMonths' : months === 12 ? 'oneYear' : 'longTerm']
    .map(([name, category, weight]) => ({ name, category, weight })),
}));

const STOP_LOSS_BY_MONTHS = Object.freeze({ 6: 8, 12: 12, 24: 18, 36: 25, 60: 35 });

const RISK_LEVELS = Object.freeze([
  { id: 'conservative', label: 'Conservative', stopLossPct: 8, behavior: 'Pauses at stop then resumes after recovery' },
  { id: 'balanced', label: 'Balanced', stopLossPct: 18, behavior: 'Pauses at stop then resumes after recovery' },
  { id: 'aggressive', label: 'Aggressive', stopLossPct: 35, behavior: 'Pauses at stop then resumes after recovery' },
]);
const STOP_LOSS_BY_RISK = Object.freeze(Object.fromEntries(RISK_LEVELS.map(x => [x.id, x.stopLossPct])));

const CUSTOM_ASSETS = [...new Map(PLANS.flatMap((plan) => plan.allocations)
  .map((asset) => [asset.name, asset])).values()];

function contractMaturityAt(startedAt, months) {
  const start = new Date(startedAt);
  const targetMonth = start.getMonth() + months;
  const year = start.getFullYear() + Math.floor(targetMonth / 12);
  const month = targetMonth % 12;
  const lastDay = new Date(year, month + 1, 0).getDate();
  return new Date(
    year, month, Math.min(start.getDate(), lastDay),
    start.getHours(), start.getMinutes(), start.getSeconds(), start.getMilliseconds(),
  ).getTime();
}

function calendarDaysBetween(startedAt, endedAt) {
  const start = new Date(startedAt);
  const end = new Date(endedAt);
  const startDay = Date.UTC(start.getFullYear(), start.getMonth(), start.getDate());
  const endDay = Date.UTC(end.getFullYear(), end.getMonth(), end.getDate());
  return Math.round((endDay - startDay) / 86_400_000);
}

return { PLANS, RISK_LEVELS, STOP_LOSS_BY_RISK, CUSTOM_ASSETS, STOP_LOSS_BY_MONTHS, contractMaturityAt, calendarDaysBetween };
})();
