document.addEventListener('click',e=>{const b=e.target.closest('[data-add-funds]');if(b)openAddFunds(b.dataset.addFunds)});
$('add-funds-source').addEventListener('change',()=>{$('add-funds-available').textContent=amount(state?.wallet?.[$('add-funds-source').value]||0)});
$('add-funds-form').addEventListener('submit',async e=>{e.preventDefault();const err=$('add-funds-error');err.textContent='';try{await post('/api/market/add-funds',{positionId:Number($('add-funds-dialog').dataset.positionId),amount:Number($('add-funds-amount').value),source:$('add-funds-source').value});$('add-funds-dialog').close();await refreshState();notice('Funds added to the active plan.')}catch(x){err.textContent=x.message}});
$('plan-form').addEventListener('submit',e=>{e.preventDefault();submitPlan(Number($('invest-amount').value),plan.months,STOP_LOSS_BY_RISK[$('invest-risk').value],'plan-error',$('invest-risk').value)});$('details-invest-button').addEventListener('click',()=>{if($('details-dialog').open)$('details-dialog').close();open('plan-dialog')});
function updateInvestAvailable(){const src=$('invest-source')?.value||'deposit';$('invest-available').textContent=amount(state?.wallet?.[src]||0)}
$('invest-source').addEventListener('change',updateInvestAvailable);function formatPlanTerms(months,risk){const lang=localStorage.getItem('you-invest-language')||'en';return translateText(months+' months',lang)+' · '+translateText(risk.label,lang)+' '+translateText('risk',lang)+' · '+translateText('fixed',lang)+' '+risk.stopLossPct+'% '+translateText('stop',lang)+'. '+translateText('Reference values are not guaranteed.',lang)}function formatPlanStopNote(risk){const lang=localStorage.getItem('you-invest-language')||'en';return risk.stopLossPct+'% '+translateText('fixed stop',lang)+' · '+translateText(risk.behavior,lang)+' · '+translateText('checked when market data refreshes.',lang)}$('invest-risk').addEventListener('change',()=>{const risk=RISK_LEVELS.find(x=>x.id===$('invest-risk').value)||RISK_LEVELS[1];$('plan-terms').textContent=formatPlanTerms(plan.months,risk);$('plan-stop-note').textContent=formatPlanStopNote(risk)});
function selectPlan(months,show){
  plan=PLANS.find(p=>p.months===months)||PLANS[0];market();
  if($('market-plan-months'))$('market-plan-months').value=String(months);
  if(show){
    resetMarketAllocationPicker('dialog-plan');
    $('plan-risk-ack').checked=false;
    const risk=RISK_LEVELS.find(x=>x.id===$('invest-risk').value)||RISK_LEVELS[1],lang=localStorage.getItem('you-invest-language')||'en';
    $('plan-dialog-title').textContent=translateText(plan.name,lang);
    $('plan-terms').textContent=formatPlanTerms(months,risk);
    $('plan-stop-note').textContent=formatPlanStopNote(risk);
    updateInvestAvailable();$('invest-amount').value='50';$('plan-dialog').scrollTop=0;open('plan-dialog')
  }
}
async function submitPlan(sum,months,stop,errorId,riskLevel){const err=$(errorId);if(err)err.textContent='';if(!token){auth('login');return}const allocation=marketAllocationForPicker(document.querySelector('[data-market-allocation-picker="'+(errorId==='plan-error'?'dialog-plan':'market-plan')+'"]'));if(allocation.length<3){if(err)err.textContent='Select at least 3 assets.';return}const ack=$(errorId==='plan-error'?'plan-risk-ack':'market-plan-risk-ack');if(!ack?.checked){if(err)err.textContent='Please acknowledge the market and loss risks before starting this plan.';return}const btn=$(errorId==='plan-error'?'confirm-plan-button':'market-plan-submit');if(btn)btn.disabled=true;try{await post('/api/market/invest',{amount:sum,months:months,riskLevel:riskLevel||'balanced',riskAcknowledged:true,source:document.getElementById('market-plan-source')?.value||$('invest-source')?.value||'deposit',allocations:allocation,electricityMarket:localStorage.getItem('you-invest-electricity-market')||'DE-LU'});$('plan-dialog').close();ack.checked=false;await refreshState();go('investments');notice('Plan started with '+(RISK_LEVELS.find(x=>x.id===(riskLevel||'balanced'))?.label||'Balanced')+' risk.')}catch(e){if(err)err.textContent=e.message;else notice(e.message,true)}finally{if(btn)btn.disabled=false}}
function priceSeries(key,r){if(!histories)return[];const rObj=rangeData.find(x=>x[0]===r)||rangeData[4],source=r==='1d'?(histories.intraday?.[key]||[]):(histories.histories?.[key]||[]),cut=Date.now()-rObj[2]*86400000,points=source.filter(p=>Number(p.time)>=cut&&Number.isFinite(Number(p.value))).map(p=>({time:Number(p.time),value:Number(p.value)}));if(points.length<=240)return points;return Array.from({length:240},(_,i)=>points[Math.round(i*(points.length-1)/239)])}
