async function redeemAllMarketGains(button){const positions=(state?.marketPositions||[]).filter(p=>(p.status==='active'||p.status==='paused')&&Number(p.currentValue)-Number(p.amount)>=0.001);if(!positions.length){notice('No gains are currently available.',true);return}button.disabled=true;let total=0,failures=0;try{for(const position of positions){try{const result=await post('/api/market/redeem-gains',{positionId:Number(position.id)});total+=Number(result.redeemed||0)}catch{failures++}}await refreshState();if(total>0)notice('Redeemed '+total.toFixed(3)+' USDT to your internal balance.'+(failures?' Some plans changed; refresh and retry remaining gains.':''));else notice('No gains could be redeemed. Refresh the account and try again.',true)}finally{button.disabled=false;updateRedeemControls()}}
