function weightedSeries(months,r){const planData=PLANS.find(p=>p.months===months);if(!planData)return[];const sets=planData.allocations.map(a=>({key:assetKeys[a.name],weight:a.weight,points:priceSeries(assetKeys[a.name],r)})).filter(x=>x.points.length>1);if(!sets.length)return[];const start=Math.max(...sets.map(x=>x.points[0].time)),end=Date.now(),out=[];for(let i=0;i<65;i++){const time=start+(end-start)*i/64;let val=0,w=0;sets.forEach(x=>{const p=x.points.reduce((b,n)=>Math.abs(n.time-time)<Math.abs(b.time-time)?n:b,x.points[0]);if(x.points[0].value>0){val+=x.weight/100*p.value/x.points[0].value;w+=x.weight/100}});if(w)out.push({time,value:100*val/w})}return out}
function renderMarketTrend(){const box=$('market-trend-indicator'),label=$('market-trend-label'),value=$('market-trend-value'),lang=localStorage.getItem('you-invest-language')||'en';if(!box||!label||!value)return;const points=weightedSeries(plan.months,'1m');if(points.length<2){box.className='market-trend neutral';label.textContent=translateText('Trend non disponibile',lang);value.textContent=translateText('Dati di mercato insufficienti · non è una raccomandazione',lang);return}const first=Number(points[0].value),last=Number(points[points.length-1].value),change=first?100*(last-first)/first:0,kind=change>0.5?'up':change<-.5?'down':'flat';box.className='market-trend '+kind;label.textContent=translateText(kind==='up'?'Trend recente in rialzo':kind==='down'?'Trend recente in calo':'Trend recente laterale',lang);value.textContent=(change>0?'+':'')+change.toFixed(3)+'% · '+translateText('dato descrittivo, non indica il momento migliore per investire',lang)}const assetGroups=[['Market indices',['S&P 500','NASDAQ','Dow Jones','Russell 2000']],['Commodities',['Gold','Oil','Silver','Natural gas','Copper']],['Companies & funds',['Tesla','Artificial intelligence']],['Digital assets',['Bitcoin','Ethereum']],['Foreign exchange',['EUR/USD']],['Electricity markets',['Electricity']]];
function market(){const list=$('asset-market-list');if(!list)return;const lang=localStorage.getItem('you-invest-language')||'en';list.innerHTML=assetGroups.map(([group,names],index)=>'<details class="asset-market-group"'+(index===0?' open':'')+'><summary><span>'+esc(translateText(group,lang))+'</span><small>'+names.length+'</small></summary><div class="asset-market-group-items">'+names.map(n=>{const q=getMarketQuote(n);return '<button class="asset-market-row" type="button" data-asset="'+esc(n)+'"><span class="asset-symbol">'+esc(n.slice(0,2).toUpperCase())+'</span><span class="asset-market-name"><b>'+esc(translateText(n,lang))+'</b><small>'+esc(translateText(q?.provider||'Quote unavailable',lang))+' · '+esc(q?.symbol||'')+'</small></span><span class="asset-market-price"><b>'+(q?quotePrice(q.price):'—')+'</b><small>'+esc(q?.unit||q?.currency||'')+'</small></span></button>'}).join('')+'</div></details>').join('');list.onclick=e=>{const b=e.target.closest('[data-asset]');if(b&&list.contains(b))assetDialog(b.dataset.asset)};const selectors=$('plan-chart-selectors');selectors.innerHTML=rangeData.map(x=>'<button type="button" data-range="'+x[0]+'" class="chart-selector '+(x[0]===range?'active':'')+'">'+x[1]+'</button>').join('');selectors.querySelectorAll('[data-range]').forEach(b=>b.addEventListener('click',()=>{range=b.dataset.range;market()}));$('plan-history-chart').innerHTML=chart(weightedSeries(plan.months,range),translateText(plan.name,lang));wireChart($('plan-history-chart'));renderMarketTrend();}

function mergeLiveAssetHistory(){if(!histories?.histories)return;const now=Date.now();for(const [name,key] of Object.entries(assetKeys)){const value=Number(getMarketQuote(name)?.price);if(!Number.isFinite(value)||value<=0)continue;for(const series of [histories.histories?.[key],histories.intraday?.[key]]){if(!Array.isArray(series))continue;const last=series[series.length-1];if(last&&now-Number(last.time)<60000){last.time=now;last.value=value}else series.push({time:now,value})}}}function updateAssetQuoteRows(){const list=$('asset-market-list');if(!list)return;const lang=localStorage.getItem('you-invest-language')||'en';list.querySelectorAll('[data-asset]').forEach(row=>{const q=getMarketQuote(row.dataset.asset),provider=row.querySelector('.asset-market-name small'),price=row.querySelector('.asset-market-price b'),unit=row.querySelector('.asset-market-price small');if(provider)provider.textContent=translateText(q?.provider||'Quote unavailable',lang)+' · '+(q?.symbol||'');if(price)price.textContent=q?quotePrice(q.price):'—';if(unit)unit.textContent=q?(q.unit||q.currency||''):''})}let selectedAssetName=null,selectedAssetRange='6m';
function updateAssetDetailQuote(name){const q=getMarketQuote(name);$('asset-detail-quote').innerHTML=q?'<b>'+quotePrice(q.price)+' '+esc(q.currency||'USD')+'</b><small>'+esc(q.instrument||'')+' · '+esc(q.provider||'')+' · '+(q.marketAt?new Date(q.marketAt).toLocaleString(getLocale()):'')+'</small>':'<p>Quote unavailable.</p>'}
function renderSelectedAssetChart(){if(!selectedAssetName)return;const key=assetKeys[selectedAssetName],lang=localStorage.getItem('you-invest-language')||'en',title=$('asset-detail-title'),target=$('asset-detail-chart');if(!key||!title||!target)return;title.dataset.asset=selectedAssetName;title.textContent=translateText(selectedAssetName,lang);updateAssetDetailQuote(selectedAssetName);target.innerHTML=chart(priceSeries(key,selectedAssetRange),translateText(selectedAssetName,lang));wireChart(target)}
function assetDialog(name){const key=assetKeys[name],lang=localStorage.getItem('you-invest-language')||'en';if(!key)return;selectedAssetName=name;selectedAssetRange='6m';const selector=$('electricity-market-control'),powerSelect=$('electricity-market-select');if(selector&&powerSelect){selector.hidden=name!=='Electricity';const options=[['DE-LU','Germany–Luxembourg'],['FR','France'],['NL','Netherlands'],['BE','Belgium'],['AT','Austria'],['CH','Switzerland'],['DK1','Denmark West'],['DK2','Denmark East']];powerSelect.innerHTML=options.map(([value,label])=>'<option value="'+value+'">'+esc(translateText(label,lang))+'</option>').join('');powerSelect.value=electricityMarket();powerSelect.onchange=()=>{localStorage.setItem('you-invest-electricity-market',powerSelect.value);const quoteTask=refreshMarketQuotes(),historyTask=refreshMarketHistory();quoteTask.then(()=>{updateAssetQuoteRows();updateAssetDetailQuote('Electricity')});historyTask.then(()=>{histories=getMarketHistory();renderSelectedAssetChart()})};}const ranges=$('asset-chart-ranges');ranges.innerHTML=rangeData.map(x=>'<button type="button" data-range="'+x[0]+'" class="asset-chart-range '+(x[0]===selectedAssetRange?'active':'')+'">'+x[1]+'</button>').join('');ranges.querySelectorAll('[data-range]').forEach(b=>b.addEventListener('click',()=>{ranges.querySelectorAll('.active').forEach(x=>x.classList.remove('active'));b.classList.add('active');selectedAssetRange=b.dataset.range;renderSelectedAssetChart()}));renderSelectedAssetChart()}
let marketLoadPromise=null,marketHistoryLoadPromise=null;async function loadMarket(){if(marketLoadPromise)return marketLoadPromise;marketLoadPromise=(async()=>{try{histories=getMarketHistory();market();renderSelectedAssetChart();await refreshMarketQuotes();market();renderSelectedAssetChart();if(selectedInvestmentId&&$('investment-detail-dialog').open)renderInvestmentDetail(selectedInvestmentId);if(!marketHistoryLoadPromise)marketHistoryLoadPromise=refreshMarketHistory().then(()=>{histories=getMarketHistory();if(selectedAssetName)renderSelectedAssetChart();if(selectedInvestmentId&&$('investment-detail-dialog').open)renderInvestmentDetail(selectedInvestmentId)}).finally(()=>{marketHistoryLoadPromise=null})}catch(e){console.warn('Market feed unavailable',e)}})();try{return await marketLoadPromise}finally{marketLoadPromise=null}}



