$('request-verification-button').addEventListener('click',()=>{if(state?.user?.emailVerified){notice('Email is already verified.');return}open('verification-dialog')});
$('request-email-verification').addEventListener('click',async()=>{const button=$('request-email-verification');button.disabled=true;try{await post('/api/verification/request',{});const lang=localStorage.getItem('you-invest-language')||'en';notice(translateText('Verification request sent. Wait for the code sent by email, then enter it here.',lang))}catch(x){notice(x.message,true)}finally{button.disabled=false}});
$('verification-otp-form').addEventListener('submit',async e=>{e.preventDefault();const err=$('verification-otp-error');err.textContent='';try{await post('/api/verification/verify-otp',{otp:$('verification-otp').value.trim()});$('verification-dialog').close();await refreshState();notice('Email verified.')}catch(x){err.textContent=x.message}});

$('change-password-button').addEventListener('click',()=>open('password-dialog'));
$('password-form').addEventListener('submit',async e=>{e.preventDefault();const err=$('password-error');err.textContent='';if($('new-password').value!==$('confirm-new-password').value){err.textContent='Passwords do not match.';return}try{await post('/api/change-password',{current:$('current-password').value,next:$('new-password').value});$('password-dialog').close();$('password-form').reset();notice('Password updated.')}catch(x){err.textContent=x.message}});
$('copy-invite-link').addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('invite-link').value);notice('Invite link copied.')}catch{ $('invite-link').select();document.execCommand('copy');notice('Invite link copied.')}});
$('mark-notifications-read').addEventListener('click',async()=>{try{await post('/api/notifications/read',{all:true});await refreshNotifications();$('notifications-dialog').close();notice('Notifications marked read.')}catch(e){notice(e.message,true)}});
async function refreshNotifications(){if(!token)return;if(notificationsLoading){notificationRefreshQueued=true;return}notificationsLoading=true;try{const data=await api('/api/notifications');const lang=localStorage.getItem('you-invest-language')||'en',unread=Number(data.unread)||0,badge=$('notification-count');badge.textContent=unread>99?'99+':String(unread);badge.hidden=unread===0;$('notification-dot').hidden=unread===0;$('open-notifications').setAttribute('aria-label',translateText('Notifications',lang)+(unread?' · '+unread+' '+translateText('unread',lang):''));$('mark-notifications-read').hidden=unread===0;const rows=data.notifications||[],signature=lang+'::'+rows.map(n=>[n.id,n.title,n.message,n.created_at,n.read_at].join('|')).join('::');if(signature!==notificationSignature){const oldIds=new Set(notificationIds);const newUnread=rows.filter(n=>!n.read_at&&!oldIds.has(String(n.id)));notificationSignature=signature;notificationIds=rows.map(n=>String(n.id));$('notification-list').innerHTML=rows.map(n=>'<article class="notification-row '+(n.read_at?'':'unread')+'"><b>'+esc(translateText(n.title,lang))+'</b><small>'+new Date(Number(n.created_at)).toLocaleString(getLocale())+'</small><p>'+esc(translateText(n.message,lang))+'</p></article>').join('');if(notificationInitialized&&newUnread.length){const n=newUnread[0];notice(translateText(n.title,lang)||translateText('New notification',lang))}}notificationInitialized=true;$('notifications-empty').hidden=rows.length>0;translatePage(lang)}catch(e){console.warn('Notifications unavailable',e)}finally{notificationsLoading=false;if(notificationRefreshQueued){notificationRefreshQueued=false;queueMicrotask(()=>refreshNotifications())}}}
function stopNotificationStream(){const active=notificationStreamController;notificationStreamController=null;if(active)active.abort();if(notificationStreamRetry){clearTimeout(notificationStreamRetry);notificationStreamRetry=null}}
function connectNotificationStream(){if(!token||notificationStreamController||typeof AbortController==='undefined')return;const controller=new AbortController();notificationStreamController=controller;(async()=>{try{const response=await fetch('/api/notifications/stream',{headers:{'x-session-token':token,'accept':'text/event-stream'},cache:'no-store',signal:controller.signal});if(!response.ok||!response.body)throw new Error('Realtime notification stream unavailable.');const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='';while(true){const part=await reader.read();if(part.done)break;buffer+=decoder.decode(part.value,{stream:true});let boundary;while((boundary=buffer.indexOf('\n\n'))!==-1){const event=buffer.slice(0,boundary);buffer=buffer.slice(boundary+2);if(event.includes('event: ready')||event.includes('event: notification'))refreshNotifications()}}}catch(error){if(error.name!=='AbortError')console.warn('Realtime notifications disconnected',error)}finally{if(notificationStreamController===controller)notificationStreamController=null;if(token&&!notificationStreamController&&!notificationStreamRetry){refreshNotifications();notificationStreamRetry=setTimeout(()=>{notificationStreamRetry=null;connectNotificationStream()},2000)}}})()}
$('open-notifications').addEventListener('click',async()=>{await refreshNotifications();open('notifications-dialog')});
function isEditingFormField(){const active=document.activeElement;return !!(active&&(active.matches('input,select,textarea')||active.isContentEditable))}
function walletOtpFocused(){return state?.sensitiveAction?.action==='wallet-change'&&document.activeElement?.id==='wallet-otp'}
async function refreshState(preserveAssets=false){if(!token||stateLoading||(isEditingFormField()&&!walletOtpFocused()))return;stateLoading=true;try{const updated=await api('/api/me');if(isEditingFormField()&&!walletOtpFocused())return;state=updated;if(preserveAssets){renderBalance();renderInvestments()}else render();if(selectedInvestmentId&&$('investment-detail-dialog').open)renderInvestmentDetail(selectedInvestmentId)}catch(e){if(e.status===401)logout();else console.warn(e)}finally{stateLoading=false}}
function connectAssetPriceStream(){
  if(marketQuoteStream||typeof EventSource==='undefined')return;
  marketQuoteStream=new EventSource('/api/asset-prices/stream');
  marketQuoteStream.addEventListener('quotes',event=>{
    try{
      applyMarketQuoteData(JSON.parse(event.data));
      histories=getMarketHistory();
      mergeLiveAssetHistory();
      const assetsView=['assets','catalog'].includes($('app-shell').dataset.view);
      if(assetsView)updateAssetQuoteRows();else market();
      const openAsset=$('asset-detail-title').dataset.asset;
      if(openAsset){if(assetsView){updateAssetDetailQuote(openAsset);const chart=$('asset-detail-chart').querySelector('.data-chart');if(!chart||(document.activeElement!==chart&&!chart.matches(':hover')))renderSelectedAssetChart()}else renderSelectedAssetChart()}
      if(token&&!assetsView)refreshState();
    }catch(error){console.warn('Live asset update failed',error)}
  });
}
function startPolling(){updateAdminAutoRefreshToggle();if(poll)clearInterval(poll);if(token){refreshState();connectNotificationStream()}else if(adminToken&&$('view-admin').classList.contains('active'))renderAdmin();loadMarket().then(connectAssetPriceStream);applyLanguage();poll=setInterval(()=>{if(document.visibilityState!=='visible'||(!token&&!adminToken)||(adminToken&&localStorage.getItem('you-invest-admin-auto-refresh')==='off')||isEditingFormField()||document.querySelector('dialog[open]')||document.querySelector('[aria-busy="true"]')||pendingPostRequests.size>0)return;const button=$('refresh-account');if(button&&!button.disabled)button.click()},5000)}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&token&&(!isEditingFormField()||walletOtpFocused())){refreshState();if(!isEditingFormField())refreshNotifications()}});

let supportThread=null,supportMessages=[],adminSupportThreadId=null,supportSending=false,adminSupportSending=false,supportSelectedRating=0,supportFeedbackSubmittedThread=0;
const supportFacts=[{"keys":["deposit","deposits","depositi","deposito","usdt","bitcoin","btc","bnb","trc20","bep-20","bep20","rete","network","address","indirizzo","dépôt","dépôts","deposito","depósitos","einzahlung","einzahlungen","einzahlen","depósito","depósitos","जमा","जमाकर्ता","充值","存款"],"info":"Depositi: la piattaforma consente di inviare una richiesta, che viene controllata manualmente; il modulo non trasferisce fondi. USDT è supportato su BNB Smart Chain (BEP-20) e TRON (TRC-20). Bitcoin accetta BTC soltanto, non USDT. L’indirizzo deve essere verificato dall’operatore e va scelta la rete esatta.","translations":["Deposits: The platform records requests for manual review; submitting the form does not transfer funds. USDT is supported on BNB Smart Chain (BEP-20) and TRON (TRC-20). Bitcoin accepts BTC only, not USDT. Have the receiving address verified by an operator and select the exact network.","Dépôts : la plateforme enregistre les demandes pour examen manuel ; l’envoi du formulaire ne transfère pas de fonds. USDT est pris en charge sur BNB Smart Chain (BEP-20) et TRON (TRC-20). Bitcoin accepte uniquement le BTC, pas l’USDT. Faites vérifier l’adresse de réception par un opérateur et sélectionnez le réseau exact.","Depósitos: la plataforma registra las solicitudes para revisión manual; enviar el formulario no transfiere fondos. Se admite USDT en BNB Smart Chain (BEP-20) y TRON (TRC-20). Bitcoin acepta solo BTC, no USDT. Solicita a un operador que verifique la dirección de recepción y selecciona la red exacta.","Einzahlungen: Die Plattform erfasst Anfragen zur manuellen Prüfung; das Absenden des Formulars überträgt kein Geld. USDT wird auf BNB Smart Chain (BEP-20) und TRON (TRC-20) unterstützt. Bitcoin akzeptiert nur BTC, kein USDT. Lass die Empfangsadresse von einem Operator prüfen und wähle exakt das richtige Netzwerk.","Depósitos: a plataforma regista pedidos para análise manual; enviar o formulário não transfere fundos. USDT é aceite na BNB Smart Chain (BEP-20) e na TRON (TRC-20). Bitcoin aceita apenas BTC, não USDT. Peça a um operador para verificar o endereço de receção e escolha a rede exata.","जमा: प्लेटफ़ॉर्म अनुरोध को मैन्युअल समीक्षा के लिए दर्ज करता है; फ़ॉर्म भेजने से धनराशि स्थानांतरित नहीं होती। USDT, BNB Smart Chain (BEP-20) और TRON (TRC-20) पर समर्थित है। Bitcoin में केवल BTC स्वीकार होता है, USDT नहीं। प्राप्ति पते की ऑपरेटर से पुष्टि करें और सही नेटवर्क चुनें।","存款：平台会记录申请并进行人工审核；提交表单不会转移资金。USDT 支持 BNB Smart Chain (BEP-20) 和 TRON (TRC-20)。Bitcoin 只接受 BTC，不接受 USDT。请让客服核实收款地址，并准确选择网络。","Depositi: la piattaforma consente di inviare una richiesta, che viene controllata manualmente; il modulo non trasferisce fondi. USDT è supportato su BNB Smart Chain (BEP-20) e TRON (TRC-20). Bitcoin accetta BTC soltanto, non USDT. L’indirizzo deve essere verificato dall’operatore e va scelta la rete esatta."]},{"keys":["withdraw","withdrawal","withdrawals","preliev","ritir","cashout","verifica","verify","email","e-mail","otp","codice","retrait","retraits","retiro","retiros","auszahlung","auszahlungen","levantamento","levantamentos","saque","saques","निकासी","ईमेल","提现","取款","验证"],"info":"Prelievi: la verifica email richiesta si avvia dalla sezione Profilo. Le richieste di prelievo sono esaminate manualmente; per verificare l’email si richiede un codice monouso e non bisogna mai condividere password, OTP, chiavi private o frasi di recupero in chat.","translations":["Withdrawals: Start the required email verification from Profile. Withdrawal requests are reviewed manually. Email verification uses a one-time code; never share passwords, OTPs, private keys, or recovery phrases in chat.","Retraits : lancez la vérification de l’e-mail requise depuis le Profil. Les demandes de retrait sont examinées manuellement. La vérification utilise un code à usage unique ; ne partagez jamais de mot de passe, d’OTP, de clé privée ni de phrase de récupération dans le chat.","Retiros: inicia la verificación de correo requerida desde Perfil. Las solicitudes de retiro se revisan manualmente. La verificación usa un código de un solo uso; nunca compartas contraseñas, códigos OTP, claves privadas ni frases de recuperación en el chat.","Auszahlungen: Starte die erforderliche E-Mail-Verifizierung im Profil. Auszahlungsanfragen werden manuell geprüft. Für die E-Mail-Verifizierung wird ein Einmalcode benötigt. Teile niemals Passwörter, OTPs, private Schlüssel oder Wiederherstellungsphrasen im Chat.","Levantamentos: inicie a verificação de e-mail necessária em Perfil. Os pedidos de levantamento são analisados manualmente. A verificação usa um código de utilização única; nunca partilhe palavras-passe, códigos OTP, chaves privadas ou frases de recuperação no chat.","निकासी: आवश्यक ईमेल सत्यापन प्रोफ़ाइल अनुभाग से शुरू करें। निकासी अनुरोधों की मैन्युअल समीक्षा होती है। ईमेल सत्यापन के लिए एक बार उपयोग होने वाला कोड चाहिए; चैट में पासवर्ड, OTP, निजी कुंजी या रिकवरी वाक्यांश कभी साझा न करें।","提现：请在“个人资料”中启动所需的邮箱验证。提现申请会经过人工审核。邮箱验证使用一次性验证码；切勿在聊天中分享密码、OTP、私钥或助记词。","Prelievi: la verifica email richiesta si avvia dalla sezione Profilo. Le richieste di prelievo sono esaminate manualmente; per verificare l’email si richiede un codice monouso e non bisogna mai condividere password, OTP, chiavi private o frasi di recupero in chat."]},{"keys":["account","profil","password","login","accesso","registr","username","utente","compte","mot de passe","cuenta","contraseña","konto","passwort","senha","conta","खाता","पासवर्ड","账户","密码","登录"],"info":"Account: i dati e le richieste sono memorizzati nel database della piattaforma. La password può essere aggiornata dalle impostazioni Profilo se si conosce quella attuale. Per recuperarla si richiede un codice monouso tramite email registrata, emesso dall’operatore.","translations":["Account: your data and requests are stored in the platform database. You can change your password in Profile settings if you know the current one. To recover it, request a one-time code through your registered email; an operator must issue the code.","Compte : vos données et demandes sont enregistrées dans la base de données de la plateforme. Vous pouvez modifier votre mot de passe dans les paramètres du Profil si vous connaissez l’actuel. Pour le récupérer, demandez un code à usage unique via votre e-mail enregistré ; un opérateur doit émettre ce code.","Cuenta: tus datos y solicitudes se guardan en la base de datos de la plataforma. Puedes cambiar la contraseña desde los ajustes de Perfil si conoces la actual. Para recuperarla, solicita un código de un solo uso en tu correo registrado; un operador debe emitirlo.","Konto: Deine Daten und Anfragen werden in der Plattformdatenbank gespeichert. Wenn du dein aktuelles Passwort kennst, kannst du es in den Profileinstellungen ändern. Zur Wiederherstellung benötigst du einen Einmalcode an deine registrierte E-Mail-Adresse, der von einem Operator ausgestellt wird.","Conta: os seus dados e pedidos são guardados na base de dados da plataforma. Pode alterar a palavra-passe nas definições do Perfil se souber a atual. Para a recuperar, peça um código de utilização única através do e-mail registado; o código tem de ser emitido por um operador.","खाता: आपका डेटा और अनुरोध प्लेटफ़ॉर्म के डेटाबेस में संग्रहीत हैं। वर्तमान पासवर्ड मालूम हो तो उसे प्रोफ़ाइल सेटिंग्स में बदल सकते हैं। पासवर्ड पुनर्प्राप्त करने के लिए पंजीकृत ईमेल पर एक बार उपयोग होने वाला कोड माँगें; यह कोड ऑपरेटर जारी करता है।","账户：您的数据和申请存储在平台数据库中。如果知道当前密码，可以在个人资料设置中修改。要找回密码，请通过已注册邮箱申请一次性验证码；验证码由客服发放。","Account: i dati e le richieste sono memorizzati nel database della piattaforma. La password può essere aggiornata dalle impostazioni Profilo se si conosce quella attuale. Per recuperarla si richiede un codice monouso tramite email registrata, emesso dall’operatore."]},{"keys":["invest","investment","piano","portafoglio","portfolio","rendimento","profit","guadagn","rischio","stop","perdita","portefeuille","cartera","inversión","inversion","anlage","investimento","investimentos","निवेश","जोखिम","投资","组合","风险"],"info":"Portafogli: sono piani di tracciamento con valore variabile calcolato da quotazioni pubbliche e controlli al refresh. Non acquistano né custodiscono gli asset, non sono ordini di borsa e non garantiscono rendimenti; il valore può scendere e sono possibili perdite.","translations":["Portfolios: these are tracking plans with variable values calculated from public quotes and checked when refreshed. They do not buy or hold assets, are not stock-market orders, and do not guarantee returns; values can fall and losses are possible.","Portefeuilles : il s’agit de plans de suivi dont la valeur varie selon les cotations publiques et les contrôles lors de l’actualisation. Ils n’achètent ni ne conservent d’actifs, ne constituent pas des ordres de bourse et ne garantissent aucun rendement ; la valeur peut baisser et des pertes sont possibles.","Carteras: son planes de seguimiento con un valor variable calculado a partir de cotizaciones públicas y comprobado al actualizar. No compran ni custodian activos, no son órdenes bursátiles y no garantizan rendimientos; el valor puede bajar y es posible sufrir pérdidas.","Portfolios: Dies sind Tracking-Pläne mit variablem Wert auf Grundlage öffentlicher Kurse, der beim Aktualisieren geprüft wird. Sie kaufen oder verwahren keine Vermögenswerte, sind keine Börsenaufträge und garantieren keine Rendite; Werte können fallen und Verluste sind möglich.","Carteiras: são planos de acompanhamento com valor variável calculado a partir de cotações públicas e verificado durante a atualização. Não compram nem guardam ativos, não são ordens de bolsa e não garantem rendimentos; o valor pode descer e podem ocorrer perdas.","पोर्टफ़ोलियो: ये सार्वजनिक बाज़ार भावों से गणना किए गए परिवर्तनीय मूल्य वाले ट्रैकिंग प्लान हैं, जिनकी जाँच अपडेट के समय होती है। ये संपत्तियाँ खरीदते या सुरक्षित नहीं रखते, शेयर बाज़ार के ऑर्डर नहीं हैं और रिटर्न की गारंटी नहीं देते; मूल्य घट सकता है और नुकसान संभव है।","投资组合：这些是跟踪计划，价值根据公开报价计算，并在刷新时检查。平台不会购买或托管这些资产；它们不是证券交易订单，也不保证收益。价值可能下跌，存在亏损风险。","Portafogli: sono piani di tracciamento con valore variabile calcolato da quotazioni pubbliche e controlli al refresh. Non acquistano né custodiscono gli asset, non sono ordini di borsa e non garantiscono rendimenti; il valore può scendere e sono possibili perdite."]},{"keys":["prezzo","quotaz","market","mercato","asset","bitcoin","ethereum","gold","oro","oil","petrol","tesla","nasdaq","s&p","elettric","electric","intelligenza artificiale","marché","marchés","mercado","mercados","markt","märkte","बाजार","बाज़ार","市场","行情"],"info":"Mercati: la piattaforma mostra quotazioni pubbliche di riferimento per asset come oro, petrolio, elettricità, S&P 500, NASDAQ, Tesla, intelligenza artificiale, Bitcoin ed Ethereum. Le quotazioni sono informative e la piattaforma non è collegata a broker, exchange o servizi di regolamento.","translations":["Markets: the platform displays public reference quotes for assets such as gold, oil, electricity, the S&P 500, NASDAQ, Tesla, artificial intelligence, Bitcoin, and Ethereum. Quotes are informational; the platform is not connected to a broker, exchange, or settlement service.","Marchés : la plateforme affiche des cotations publiques de référence pour des actifs tels que l’or, le pétrole, l’électricité, le S&P 500, le NASDAQ, Tesla, l’intelligence artificielle, Bitcoin et Ethereum. Ces cotations sont informatives ; la plateforme n’est liée à aucun courtier, exchange ou service de règlement.","Mercados: la plataforma muestra cotizaciones públicas de referencia de activos como oro, petróleo, electricidad, S&P 500, NASDAQ, Tesla, inteligencia artificial, Bitcoin y Ethereum. Las cotizaciones son informativas; la plataforma no está conectada a ningún bróker, exchange o servicio de liquidación.","Märkte: Die Plattform zeigt öffentliche Referenzkurse für Vermögenswerte wie Gold, Öl, Strom, S&P 500, NASDAQ, Tesla, künstliche Intelligenz, Bitcoin und Ethereum. Die Kurse dienen nur zur Information; die Plattform ist nicht mit einem Broker, einer Börse oder einem Abwicklungsdienst verbunden.","Mercados: a plataforma apresenta cotações públicas de referência de ativos como ouro, petróleo, eletricidade, S&P 500, NASDAQ, Tesla, inteligência artificial, Bitcoin e Ethereum. As cotações são informativas; a plataforma não está ligada a um corretor, exchange ou serviço de liquidação.","बाज़ार: प्लेटफ़ॉर्म सोना, तेल, बिजली, S&P 500, NASDAQ, Tesla, कृत्रिम बुद्धिमत्ता, Bitcoin और Ethereum जैसी संपत्तियों के सार्वजनिक संदर्भ भाव दिखाता है। ये भाव केवल जानकारी के लिए हैं; प्लेटफ़ॉर्म किसी ब्रोकर, एक्सचेंज या निपटान सेवा से जुड़ा नहीं है।","市场：平台显示黄金、石油、电力、S&P 500、NASDAQ、Tesla、人工智能、Bitcoin 和 Ethereum 等资产的公开参考报价。报价仅供参考；平台未连接经纪商、交易所或结算服务。","Mercati: la piattaforma mostra quotazioni pubbliche di riferimento per asset come oro, petrolio, elettricità, S&P 500, NASDAQ, Tesla, intelligenza artificiale, Bitcoin ed Ethereum. Le quotazioni sono informative e la piattaforma non è collegata a broker, exchange o servizi di regolamento."]},{"keys":["invita","invito","referral","commission","livello","team","invitation","invitations","invitación","invitaciones","einladung","empfehlung","convite","convites","आमंत्रण","邀请","推荐"],"info":"Inviti: la piattaforma mostra il link personale e i membri invitati per livelli; eventuali commissioni sono registrate nella pagina Inviti e dipendono dai depositi approvati indicati dalla piattaforma.","translations":["Invitations: the platform shows your personal link and invited members by level. Any commissions are recorded on the Invitations page and depend on approved deposits as shown by the platform.","Invitations : la plateforme affiche votre lien personnel et les membres invités par niveau. Les éventuelles commissions sont enregistrées sur la page Invitations et dépendent des dépôts approuvés indiqués par la plateforme.","Invitaciones: la plataforma muestra tu enlace personal y los miembros invitados por nivel. Las comisiones, si las hay, aparecen en la página Invitaciones y dependen de los depósitos aprobados que indique la plataforma.","Einladungen: Die Plattform zeigt deinen persönlichen Link und eingeladene Mitglieder nach Ebene an. Etwaige Provisionen werden auf der Seite Einladungen erfasst und richten sich nach den von der Plattform ausgewiesenen genehmigten Einzahlungen.","Convites: a plataforma apresenta o seu link pessoal e os membros convidados por nível. Eventuais comissões são registadas na página Convites e dependem dos depósitos aprovados indicados pela plataforma.","आमंत्रण: प्लेटफ़ॉर्म आपका व्यक्तिगत लिंक और स्तर के अनुसार आमंत्रित सदस्यों को दिखाता है। कोई भी कमीशन आमंत्रण पृष्ठ पर दर्ज होता है और प्लेटफ़ॉर्म द्वारा दिखाए गए स्वीकृत जमा पर निर्भर करता है।","邀请：平台会显示您的个人邀请链接及各层级的受邀成员。任何佣金都会记录在“邀请”页面，并取决于平台显示的已批准存款。","Inviti: la piattaforma mostra il link personale e i membri invitati per livelli; eventuali commissioni sono registrate nella pagina Inviti e dipendono dai depositi approvati indicati dalla piattaforma."]}];
function matchedSupportFacts(message){const text=String(message||'').toLocaleLowerCase();return supportFacts.filter(f=>f.keys.some(key=>text.includes(key)))}
function localizeSupportGuideSection(section,language){
  const clone=section.cloneNode(true),walker=document.createTreeWalker(clone,NodeFilter.SHOW_TEXT);
  let node;
  while((node=walker.nextNode())){
    const source=node.nodeValue,leading=source.match(/^\s*/)?.[0]||'',trailing=source.match(/\s*$/)?.[0]||'',core=source.slice(leading.length,source.length-trailing.length);
    if(core)node.nodeValue=leading+translateText(core,language)+trailing;
  }
  return String(clone.textContent||'').replace(/\s+/g,' ').trim();
}
function supportRuleReply(message){
  const lang=supportLanguage(),index=languages.indexOf(lang),facts=matchedSupportFacts(message),template=document.getElementById('guide-document');
  const stopWords=new Set(['come','cosa','quale','quali','dove','quando','perche','perché','sono','della','delle','degli','dallo','dalla','nella','nelle','agli','dopo','dell','delle','this','that','what','when','where','which','with','from','your','have','does','about','help','please']);
  const terms=[...new Set((String(message||'').toLocaleLowerCase().match(/[a-zà-öø-ÿ]{4,}\d*|\d{4,}/g)||[]).filter(term=>!stopWords.has(term)))];
  const sections=[...(template?.content?.querySelectorAll('.guide-section')||[])].map(section=>{
    const text=localizeSupportGuideSection(section,lang),lower=text.toLocaleLowerCase();
    return {text,score:terms.reduce((score,term)=>score+(lower.includes(term)?1:0),0)};
  }).filter(section=>section.score>0).sort((a,b)=>b.score-a.score).slice(0,1);
  const answers=facts.slice(0,1).map(item=>item.translations?.[index]||item.info);
  for(const section of sections)answers.push(section.text.slice(0,420));
  const reply=answers.length?answers.join('\n\n').slice(0,1100):supportFallback();
  return facts.length||sections.length?reply+'\n\n[[GUIDE]]':reply;
}
