async function refreshAdminSupport(){if(!adminToken)return;try{const data=await api('/api/admin/support'),rows=data.conversations||[],list=$('admin-support-threads');alertForNewSupportConversations(rows);$('support-thread-count').textContent=String(rows.length);$('admin-support-empty').hidden=rows.length>0;list.innerHTML=rows.map(c=>'<button type="button" class="admin-support-open" data-support-thread="'+Number(c.id)+'"><b>@'+esc(c.username)+' <em>'+esc(c.status==='waiting'?adminSupportCopy('waitingShort'):adminSupportCopy('liveShort'))+'</em></b><small>'+esc(localizeSupportMessage(c.last_message||''))+'</small></button>').join('')}catch(e){console.warn('Support queue unavailable',e)}}
