async function refreshAdminSupportThread(){if(!adminSupportThreadId||!$('admin-support-dialog').open)return;try{const data=await api('/api/admin/support/'+adminSupportThreadId),messages=data.messages||[],latest=messages[messages.length-1],finalPending=!!(data.thread.final_message_id&&Number(data.thread.final_message_id)===Number(latest?.id));$('admin-support-title').textContent='@'+data.thread.username;$('admin-escalation-user').textContent='@'+data.thread.username+' · '+String(data.thread.identifier||'')+' · ID '+String(data.thread.user_id||'');$('admin-escalation-panel').hidden=adminUserCanManage;if(!adminUserCanManage)await refreshMyAdminGuidance(adminSupportThreadId);$('admin-support-dialog').querySelector('.eyebrow').textContent=adminSupportCopy('live');$('admin-support-status').textContent=finalPending?adminSupportCopy('closing'):data.thread.status==='waiting'?adminSupportCopy('waiting'):adminSupportCopy('live');$('admin-support-input').placeholder=adminSupportCopy('reply');$('admin-support-send').textContent=adminSupportCopy('send');$('admin-support-finish').textContent=adminSupportCopy('finish');$('admin-support-finish').hidden=finalPending;$('admin-support-input').disabled=finalPending;$('admin-support-send').disabled=finalPending;$('admin-support-messages').innerHTML=messages.map(m=>{const role=m.sender_role==='user'?'user':m.sender_role==='operator'?'operator':'assistant';return '<article class="support-message '+(role==='operator'?'user':'')+'"><small>'+esc(adminSupportCopy(role))+' · '+new Date(Number(m.created_at)).toLocaleTimeString(getLocale(),{hour:'2-digit',minute:'2-digit'})+'</small>'+esc(localizeSupportMessage(m.body))+'</article>'}).join('');$('admin-support-messages').scrollTop=$('admin-support-messages').scrollHeight}catch(e){console.warn('Support conversation unavailable',e)}}
async function refreshOperatorAdminRequests(){if(!adminUserCanManage||document.activeElement?.hasAttribute('data-admin-guidance'))return;try{const data=await api('/api/admin/support-requests'),rows=data.requests||[],list=$('operator-admin-requests'),drafts=new Map([...list.querySelectorAll('.admin-request')].map(card=>{const button=card.querySelector('[data-send-admin-guidance]'),input=card.querySelector('[data-admin-guidance]');return[Number(button?.dataset.sendAdminGuidance),input?.value||'']}));alertForNewOperatorEscalations(rows);$('operator-admin-request-count').textContent=String(rows.length);$('operator-admin-requests-empty').hidden=rows.length>0;list.innerHTML=rows.map(r=>'<article class="admin-request"><b>@'+esc(r.username||'user')+' · '+esc(r.user_identifier||'')+'</b><small>Operator @'+esc(r.operator_username||'—')+' · User ID '+esc(r.user_id||'—')+' · '+new Date(Number(r.created_at)).toLocaleString(getLocale())+'</small><p>'+esc(r.details||'')+'</p><label class="admin-guidance-field">Instructions for operator<textarea data-admin-guidance rows="2" maxlength="2000">'+esc(drafts.has(Number(r.id))?drafts.get(Number(r.id)):(r.admin_reply||''))+'</textarea></label><div><button type="button" data-send-admin-guidance="'+Number(r.id)+'">'+(r.admin_reply?'Update instructions':'Send instructions')+'</button><button type="button" data-open-admin-escalation-thread="'+Number(r.thread_id)+'">Open conversation</button><button type="button" data-resolve-admin-escalation="'+Number(r.id)+'">Mark resolved</button></div></article>').join('')}catch(error){console.warn('Operator escalation queue unavailable',error)}}
