$('admin-support-threads').addEventListener('click',e=>{const button=e.target.closest('[data-support-thread]');if(button)openAdminSupport(button.dataset.supportThread)});$('operator-admin-requests').addEventListener('click',async e=>{const openButton=e.target.closest('[data-open-admin-escalation-thread]');if(openButton){openAdminSupport(openButton.dataset.openAdminEscalationThread);return}const guidanceButton=e.target.closest('[data-send-admin-guidance]');if(guidanceButton){const card=guidanceButton.closest('.admin-request'),message=(card?.querySelector('[data-admin-guidance]')?.value||'').trim();if(!message){notice('Write instructions for the operator first.',true);return}guidanceButton.disabled=true;try{await post('/api/admin/support-requests/'+Number(guidanceButton.dataset.sendAdminGuidance)+'/reply',{message});await refreshOperatorAdminRequests();notice('Instructions sent to the operator.')}catch(error){notice(error.message,true)}finally{guidanceButton.disabled=false}return}const resolveButton=e.target.closest('[data-resolve-admin-escalation]');if(!resolveButton)return;resolveButton.disabled=true;try{await post('/api/admin/support-requests/'+Number(resolveButton.dataset.resolveAdminEscalation)+'/resolve',{});await refreshOperatorAdminRequests();notice('Operator request marked resolved.')}catch(error){notice(error.message,true)}finally{resolveButton.disabled=false}});
