async function refreshAdminPaymentDesk(){try{const data=await api('/api/admin/transactions'),deposits=(data.deposits||[]).slice().sort((a,b)=>Number(a.date)-Number(b.date)),withdrawals=(data.withdrawals||[]).slice().sort((a,b)=>Number(a.date)-Number(b.date));$('payment-incoming-count').textContent=String(deposits.length);$('payment-outgoing-count').textContent=String(withdrawals.length);$('payment-incoming-list').innerHTML=deposits.map(row=>paymentDeskItem(row,'deposit')).join('');$('payment-outgoing-list').innerHTML=withdrawals.map(row=>paymentDeskItem(row,'withdrawal')).join('');$('payment-incoming-empty').hidden=deposits.length>0;$('payment-outgoing-empty').hidden=withdrawals.length>0}catch(error){notice(error.message||'Unable to load payments.',true)}}
