$('admin-ledger-search-more').addEventListener('click',()=>loadAdminLedgerSearch(false));
function prepareAdminWorkspace(){
  const root=$('view-admin');if(!root||root.dataset.workspaceReady)return;
  root.dataset.workspaceReady='true';
  if(!root.querySelector('#admin-operator-audit-section')){
    const audit=document.createElement('div');audit.className='admin-section';audit.id='admin-operator-audit-section';audit.hidden=true;
    audit.innerHTML='<div class="section-heading"><div><p class="eyebrow">OPERATOR REVIEW</p><h2>Operator activity</h2></div><span class="count-pill" id="admin-operator-audit-count">0</span></div><div id="admin-operator-audit-list" class="admin-queue"></div><div id="admin-operator-audit-empty" class="queue-empty">No operators or review history.</div>';
    root.append(audit);
  }
  [...root.querySelectorAll(':scope > .admin-section')].forEach(section=>{
    const heading=section.querySelector(':scope > .section-heading');if(!heading)return;
    const disclosure=document.createElement('details');
    [...section.attributes].forEach(attr=>disclosure.setAttribute(attr.name,attr.value));
    disclosure.classList.add('admin-workspace-disclosure');
    const summary=document.createElement('summary');summary.className=heading.className+' admin-workspace-summary';
    while(heading.firstChild)summary.append(heading.firstChild);
    const content=document.createElement('div');content.className='admin-workspace-content';
    let node=heading.nextSibling;while(node){const next=node.nextSibling;content.append(node);node=next;}
    disclosure.append(summary,content);section.replaceWith(disclosure);
  });
  const requests=root.querySelector('#admin-request-hub');
  if(requests){
    const summary=requests.querySelector(':scope > .admin-workspace-summary');
    if(summary&&!summary.querySelector('.admin-workspace-pending-total')){
      const badge=document.createElement('span');badge.className='count-pill admin-workspace-pending-total';badge.textContent='0';badge.setAttribute('aria-label','Pending requests');summary.append(badge);
    }
  }
  const panels=[...root.querySelectorAll(':scope > .admin-section')],workspace=document.createElement('div');workspace.className='admin-workspace-shell';
  const aside=document.createElement('aside');aside.className='admin-workspace-nav';aside.setAttribute('aria-label','Admin sections');
  const navHeading=document.createElement('div');navHeading.className='admin-workspace-nav-heading';navHeading.textContent=$('admin-title')?.textContent||'Admin';
  const navList=document.createElement('div');navList.className='admin-workspace-nav-list';aside.append(navHeading,navList);
  const paymentButton=document.createElement('button');paymentButton.type='button';paymentButton.className='admin-workspace-link admin-payment-nav-link';paymentButton.hidden=true;
  const paymentRow=document.createElement('span');paymentRow.className='admin-workspace-row-number';paymentRow.textContent='01';
  const paymentCopy=document.createElement('span');paymentCopy.className='admin-workspace-link-copy';const paymentEyebrow=document.createElement('small');paymentEyebrow.textContent='SETTLEMENT';const paymentTitle=document.createElement('b');paymentTitle.textContent='Payment desk';paymentCopy.append(paymentEyebrow,paymentTitle);paymentButton.append(paymentRow,paymentCopy);
  paymentButton.addEventListener('click',()=>{navList.querySelectorAll('.admin-workspace-link').forEach(item=>item.classList.remove('is-active'));paymentButton.classList.add('is-active');paymentButton.setAttribute('aria-current','page');openAdminPaymentDesk()});navList.append(paymentButton);
  const stage=document.createElement('main');stage.className='admin-workspace-stage';stage.setAttribute('aria-label','Admin workspace');
  panels.forEach((panel,index)=>{
    const key='section-'+index;panel.dataset.adminWorkspaceKey=key;stage.append(panel);
    const summary=panel.querySelector(':scope > .admin-workspace-summary')||panel.querySelector(':scope > .admin-referral-panel > summary');
    const button=document.createElement('button');button.type='button';button.className='admin-workspace-link';button.dataset.adminWorkspaceKey=key;
    const row=document.createElement('span');row.className='admin-workspace-row-number';row.textContent=String(index+2).padStart(2,'0');
    const copy=document.createElement('span');copy.className='admin-workspace-link-copy';
    const eyebrow=document.createElement('small');eyebrow.textContent=summary?.querySelector('.eyebrow')?.textContent||'';
    const title=document.createElement('b');title.textContent=summary?.querySelector('h2')?.textContent||'Section';copy.append(eyebrow,title);
    button.append(row,copy);
    const sourceBadge=summary?.querySelector('.count-pill');
    if(sourceBadge){const badge=document.createElement('span');badge.className='admin-workspace-nav-badge';badge.textContent=sourceBadge.textContent.trim();badge.dataset.countSource=sourceBadge.id||'admin-workspace-pending-total';button.append(badge)}
    button.addEventListener('click',()=>openAdminWorkspace(key));navList.append(button);
  });
  workspace.append(aside,stage);root.append(workspace);
  const ids=['pending-otp-count','pending-wallet-count','pending-user-count','pending-deposit-count','pending-withdrawal-count'];
  const nodes=ids.map(id=>$(id)).filter(Boolean),badge=requests?.querySelector('.admin-workspace-pending-total');
  const updateBadges=()=>{
    const total=nodes.reduce((sum,node)=>sum+(Number(node.textContent)||0),0);
    if(badge&&badge.textContent!==String(total))badge.textContent=String(total);
    root.querySelectorAll('.admin-request-group .count-pill,#support-thread-count,#operator-admin-request-count').forEach(node=>node.classList.toggle('has-alert',Number(node.textContent)>0));
    syncAdminWorkspaceNavigation();
  };
  updateBadges();
  const observed=[...new Set([...nodes,$('support-thread-count'),$('operator-admin-request-count')].filter(Boolean))];
  if(observed.length){const observer=new MutationObserver(updateBadges);observed.forEach(node=>observer.observe(node,{childList:true,characterData:true,subtree:true}));root._adminBadgeObserver=observer;}
  const sectionObserver=new MutationObserver(syncAdminWorkspaceNavigation);panels.forEach(panel=>sectionObserver.observe(panel,{attributes:true,attributeFilter:['hidden']}));root._adminSectionObserver=sectionObserver;
  syncAdminWorkspaceNavigation();
}
