/* Incoming request alerts: embedded audio keeps the deployment limited to the five original files. */
const ADMIN_REQUEST_SOUND = 'data:audio/wav;base64,';
let adminIncomingRequestIds = null;
let adminSupportConversationIds = null;
let operatorEscalationRequestIds = null;
function alertAdminOperator(message){
  try{const audio=new Audio(ADMIN_REQUEST_SOUND);audio.volume=.72;const playback=audio.play();if(playback&&playback.catch)playback.catch(()=>{});}catch(error){}
  try{notice(message,false);}catch(error){}
  try{if(typeof Notification!=='undefined'&&Notification.permission==='granted')new Notification('GINZEH',{body:message,tag:'ginzeh-admin-request-'+Date.now()});}catch(error){}
}
function alertForNewAdminRequests(data){
  const groups=[['deposit',data.deposits],['withdrawal',data.withdrawals],['wallet',data.walletChanges],['email',data.emailVerifications],['verification',data.sensitiveActionVerifications],['password',data.passwordResets]];
  const current=new Set();
  for(const [kind,rows] of groups)for(const row of rows||[]){const id=row.id!=null?row.id:String(row.user_id||'')+':'+String(row.requested_at||row.created_at||'');current.add(kind+':'+id);}
  if(adminIncomingRequestIds!==null){const added=[...current].filter(id=>!adminIncomingRequestIds.has(id));if(added.length)alertAdminOperator(added.length===1?'New request received':'New requests received: '+added.length);}
  adminIncomingRequestIds=current;
}
function alertForNewSupportConversations(rows){
  const current=new Set((rows||[]).map(row=>String(row.id)));
  if(adminSupportConversationIds!==null){const added=[...current].filter(id=>!adminSupportConversationIds.has(id));if(added.length)alertAdminOperator(added.length===1?'New support request received':'New support requests received: '+added.length);}
  adminSupportConversationIds=current;
}
function alertForNewOperatorEscalations(rows){
  const current=new Set((rows||[]).map(row=>String(row.id)));
  if(operatorEscalationRequestIds!==null){const added=[...current].filter(id=>!operatorEscalationRequestIds.has(id));if(added.length)alertAdminOperator(added.length===1?'New operator request received':'New operator requests received: '+added.length);}
  operatorEscalationRequestIds=current;
}

async function refreshAdminRequestQueuesLive(){if(!adminToken||!$('view-admin').classList.contains('active')||adminQueuePollBusy)return;adminQueuePollBusy=true;try{const data=await api('/api/admin/transactions');alertForNewAdminRequests(data);const signature=JSON.stringify(data);if(signature!==adminQueueSnapshot){adminQueueSnapshot=signature;renderAdminRequestQueues(data)}}catch(error){console.warn('Admin request queue refresh unavailable',error)}finally{adminQueuePollBusy=false}}
function ensureAntifraudClearAll(lang){const refresh=$('admin-antifraud-refresh');if(!refresh)return null;let button=$('admin-antifraud-clear-all');if(!button){button=document.createElement('button');button.id='admin-antifraud-clear-all';button.type='button';button.className='danger-button';refresh.insertAdjacentElement('beforebegin',button);button.addEventListener('click',async()=>{const language=localStorage.getItem('you-invest-language')||'en';if(!confirm(translateText('Delete all antifraud history?',language)))return;button.disabled=true;try{await post('/api/admin/antifraud/delete',{all:true});notice(translateText('Antifraud history cleared.',language));button.disabled=false;await refreshAntifraudEvents()}catch(error){notice(error.message,true);button.disabled=false}})}button.textContent=translateText('Clear all',lang);return button}
let antifraudLoading=false;
async function refreshAntifraudEvents(){if(antifraudLoading||!adminToken)return;antifraudLoading=true;const list=$('admin-antifraud-list'),empty=$('admin-antifraud-empty');try{const data=await api('/api/admin/antifraud'),rows=data.events||[],lang=localStorage.getItem('you-invest-language')||'en',clearAll=ensureAntifraudClearAll(lang);if(clearAll)clearAll.hidden=false;empty.hidden=rows.length>0;if(empty.querySelector('b'))empty.querySelector('b').textContent=translateText('No shared-IP activity',lang);if(empty.querySelector('p'))empty.querySelector('p').textContent=translateText('Only events where different user accounts share an IP are shown.',lang);list.innerHTML=rows.map(row=>{const stage=Number(row.notice_stage||0),next=stage+1,shared=Number(row.shared_ip)===1,type=translateText(({registration:'Registration',deposit:'Deposit',withdrawal:'Withdrawal'})[row.event_type]||row.event_type,lang),labels=['','Alert 1 · first warning','Alert 2 · final warning','Alert 3 · account-closure notice'];return '<article class="admin-antifraud-card'+(shared?' is-flagged':'')+'"><div class="admin-antifraud-card-head"><div><b>@'+esc(row.username||'user')+'</b><small>'+esc(translateText('Account',lang))+' · '+esc(String(row.user_id||''))+'</small></div><span class="admin-antifraud-badge '+(shared?'flagged':'')+'">'+esc(translateText(shared?'Possible shared IP':'No cross-account match',lang))+'</span></div><div class="admin-antifraud-meta"><span><small>'+esc(translateText('Event',lang))+'</small><b>'+esc(type)+'</b></span><span><small>'+esc(translateText('IP address',lang))+'</small><b class="admin-antifraud-ip">'+esc(row.ip_address||translateText('No IP available',lang))+'</b></span><span><small>'+esc(translateText('Date',lang))+'</small><b>'+new Date(Number(row.created_at)).toLocaleString(getLocale())+'</b></span></div>'+(row.event_ref?'<small class="admin-antifraud-reference">'+esc(row.event_ref)+'</small>':'')+(shared&&next<=3?'<div class="admin-antifraud-send"><select data-fraud-stage="'+Number(row.id)+'" aria-label="'+esc(translateText('Select notification',lang))+'"><option value="'+next+'">'+esc(translateText(labels[next],lang))+'</option></select><button type="button" data-fraud-notify="'+Number(row.id)+'">'+esc(translateText('Send notification',lang))+'</button></div>':shared?'<p class="admin-antifraud-done">'+esc(translateText('All three notice stages have been sent.',lang))+'</p>':'<p class="admin-antifraud-muted">'+esc(translateText('No shared-IP notice can be sent for this event.',lang))+'</p>')+'<button class="danger-button" type="button" data-fraud-delete="'+Number(row.id)+'">'+esc(translateText('Delete',lang))+'</button></article>'}).join('');list.querySelectorAll('[data-fraud-notify]').forEach(button=>button.addEventListener('click',async()=>{const eventId=Number(button.dataset.fraudNotify),stage=Number(list.querySelector('[data-fraud-stage="'+eventId+'"]')?.value);button.disabled=true;try{await post('/api/admin/antifraud/notify',{eventId,stage,language:lang});notice(translateText('Notification sent.',lang));await refreshAntifraudEvents()}catch(error){notice(error.message,true);button.disabled=false}}));list.querySelectorAll('[data-fraud-delete]').forEach(button=>button.addEventListener('click',async()=>{const eventId=Number(button.dataset.fraudDelete),language=localStorage.getItem('you-invest-language')||'en';if(!confirm(translateText('Delete this antifraud record?',language)))return;button.disabled=true;try{await post('/api/admin/antifraud/delete',{eventId});notice(translateText('Antifraud record deleted.',language));await refreshAntifraudEvents()}catch(error){notice(error.message,true);button.disabled=false}}))}catch(error){notice(error.message,true)}finally{antifraudLoading=false}}
