function guideText(text,lang){return translateText(text,lang)}
const guideFrame=document.getElementById('guide-frame');
const guideTemplate=document.getElementById('guide-document');
if(guideFrame&&guideTemplate){
  const nodes=[...guideTemplate.content.childNodes];
  const style=guideTemplate.content.querySelector('style')?.textContent||'';
  const sourceMarkup=nodes.filter(node=>node.nodeType===Node.ELEMENT_NODE&&node.tagName!=='STYLE').map(node=>node.outerHTML).join('');
  const renderGuide=()=>{
    const lang=localStorage.getItem('you-invest-language')||'en';
    const parsed=new DOMParser().parseFromString('<body>'+sourceMarkup+'</body>','text/html');
    const walker=parsed.createTreeWalker(parsed.body,NodeFilter.SHOW_TEXT);
    let node;
    while((node=walker.nextNode())){
      if(node.parentElement?.closest('script,style'))continue;
      const raw=node.nodeValue,trimmed=raw.trim();
      if(!trimmed)continue;
      const leading=raw.match(/^\s*/)?.[0]||'',trailing=raw.match(/\s*$/)?.[0]||'';
      node.nodeValue=leading+guideText(trimmed,lang)+trailing;
    }
    parsed.body.querySelectorAll('[aria-label],[title],[alt],[placeholder]').forEach(element=>{
      for(const attr of ['aria-label','title','alt','placeholder']){
        const value=element.getAttribute(attr);
        if(value)element.setAttribute(attr,guideText(value.trim(),lang));
      }
    });
    const markup=parsed.body.innerHTML;
    const title=guideText('Guida',lang)+' You Invest';
    guideFrame.srcdoc='<!doctype html><html lang="'+lang+'"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#101711"><title>'+title+'</title><style>'+style+'</style></head><body>'+markup+'</body></html>';
  };
  window.addEventListener('app-language-change',renderGuide);
  const syncGuide=()=>{const open=location.hash==='#guida';guideFrame.classList.toggle('active',open);guideFrame.setAttribute('aria-hidden',String(!open));};
  window.addEventListener('hashchange',syncGuide);
  renderGuide();
  syncGuide();
}

const landingArtImages=[...document.querySelectorAll('#brand-story-dialog [data-landing-background]')];
function mountLandingArtwork(host,className){
  if(!host||!landingArtImages.length||host.querySelector('.'+className))return;
  const layer=document.createElement('div');layer.className=className;layer.setAttribute('aria-hidden','true');
  landingArtImages.forEach(source=>{const image=source.cloneNode();image.removeAttribute('data-landing-background');image.alt='';layer.appendChild(image)});
  host.prepend(layer);
}
mountLandingArtwork(document.getElementById('landing'),'landing-background-art');
mountLandingArtwork(document.querySelector('#brand-story-dialog .brand-story-card'),'brand-story-background-art');


// Admin request finder: search categories and open matching queues directly.
document.addEventListener('input',event=>{
  if(event.target?.id!=='admin-request-search')return;
  const query=event.target.value.trim().toLocaleLowerCase(),hub=$('admin-request-hub');
  if(!hub)return;
  const groups=[...hub.querySelectorAll('.admin-request-group,.admin-password-reset-requests')];
  for(const group of groups){
    const title=group.querySelector(':scope > summary')?.textContent?.toLocaleLowerCase()||'';
    const nested=[...group.querySelectorAll('.admin-request-subsection')];
    let nestedMatch=false;
    for(const item of nested){
      const matches=!query||(item.querySelector(':scope > summary')?.textContent||'').toLocaleLowerCase().includes(query);
      item.classList.toggle('request-search-hidden',!matches);
      if(query&&matches){item.open=true;nestedMatch=true;}
    }
    const matches=!query||title.includes(query)||nestedMatch;
    group.classList.toggle('request-search-hidden',!matches);
    if(query&&matches)group.open=true;
  }
});

// Full database export downloads directly to the signed-in admin's device.
async function downloadPlatformBackup(automatic=false){
  const status=$('admin-backup-status');
  if(!adminToken||!adminUserCanManage)return false;
  if(status)status.textContent=automatic?'Preparing daily backup…':'Preparing full backup…';
  try{
    const response=await fetch('/api/admin/backup/export',{method:'GET',headers:{'x-admin-token':adminToken},cache:'no-store'});
    if(!response.ok){let message='Backup failed.';try{message=(await response.json()).error||message}catch{}throw new Error(message)}
    const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');
    const stamp=new Date().toISOString().replace(/[:.]/g,'-');
    link.href=url;link.download='ginzeh-full-backup-'+stamp+'.json';link.style.display='none';document.body.append(link);link.click();link.remove();
    setTimeout(()=>URL.revokeObjectURL(url),60000);
    if(status)status.textContent=automatic?'Daily backup download started. Keep this app open and the admin signed in for future backups.':'Full JSON backup downloaded to this device.';
    return true;
  }catch(error){if(status)status.textContent='Backup unavailable: '+(error.message||'request failed');return false}
}
$('admin-backup-download')?.addEventListener('click',()=>downloadPlatformBackup(false));
const autoBackupKey='ginzeh-admin-backup-last-date';
let autoBackupBusy=false;
async function checkDailyDeviceBackup(){
  if(autoBackupBusy||!adminToken||!adminUserCanManage)return;
  const now=new Date();if(now.getHours()!==23||now.getMinutes()!==59)return;
  const date=now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0')+'-'+String(now.getDate()).padStart(2,'0');
  if(localStorage.getItem(autoBackupKey)===date)return;
  autoBackupBusy=true;
  try{if(await downloadPlatformBackup(true))localStorage.setItem(autoBackupKey,date)}finally{autoBackupBusy=false}
}
setInterval(checkDailyDeviceBackup,5000);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')checkDailyDeviceBackup()});

